def cleanup_pid():
    """Remove PID file on exit."""
    try:
        PID_FILE.unlink(missing_ok=True)
    except OSError as exc:
        LOGGER.debug("Failed to remove PID file %s: %s", PID_FILE, exc)
    if _pid_identity is None or not _owns_pid():
        raise RuntimeError("Listener does not hold the task journal ownership token")
    record = (json.dumps(event, ensure_ascii=False) + "\n").encode("utf-8")
    flags = os.O_WRONLY | os.O_CREAT | os.O_APPEND | getattr(os, "O_NOFOLLOW", 0)
    fd = os.open(EVENTS_FILE, flags, 0o600)
    with os.fdopen(fd, "ab") as handle:
        info = os.fstat(handle.fileno())
        if not stat.S_ISREG(info.st_mode) or info.st_nlink != 1:
            raise RuntimeError("Journal must be a regular task-owned file")
        if info.st_size + len(record) > MAX_EVENT_BYTES:
            raise EventBudgetExceeded(
                f"PARTIAL capture: journal byte limit {MAX_EVENT_BYTES} reached at "
                f"{EVENTS_FILE}; prior events retained; reconcile provider capture separately"
